import { IngestPipeline } from "@514labs/moose-lib";

export interface ProductEvent {
  eventId: string;
  userId: string;
  productId: string;
  eventType: "view" | "add_to_cart" | "purchase";
  timestamp: Date;
  properties: any; // JSONB from Postgres - contains price for purchase events
}

export const ProductEventPipeline = new IngestPipeline<ProductEvent>("ProductEvent", {
  table: {
    orderByFields: ["eventType", "productId", "timestamp"]
  },
  stream: true,
  ingestApi: true,
});

