import { IngestPipeline, AggregateView } from "@514labs/moose-lib";
import { ProductEvent } from "../models/ProductEvent";

export interface TopProducts {
  productId: string;
  purchaseCount: number;
  totalRevenue: number;
  lastPurchase: Date;
}

export const TopProductsView = new AggregateView<TopProducts>({
  name: "TopProducts",
  destination: "TopProducts_mv",
  materializedView: {
    query: `
      SELECT
        productId,
        count() as purchaseCount,
        sum(JSONExtractFloat(properties, 'price')) as totalRevenue,
        max(timestamp) as lastPurchase
      FROM ${ProductEvent.name}
      WHERE eventType = 'purchase'
      GROUP BY productId
      ORDER BY purchaseCount DESC, totalRevenue DESC
    `,
    orderByFields: ["purchaseCount", "totalRevenue"],
  },
});

