import { AggregateView } from "@514labs/moose-lib";

export interface ConversionFunnel {
  totalUsers: number;
  viewUsers: number;
  cartUsers: number;
  purchaseUsers: number;
  viewTocCartRate: number;
  cartToPurchaseRate: number;
  overallConversionRate: number;
}

export const ConversionFunnelView = new AggregateView<ConversionFunnel>({
  name: "ConversionFunnel",
  destination: "ConversionFunnel_mv",
  materializedView: {
    query: `
      SELECT
        count(DISTINCT userId) as totalUsers,
        countIf(DISTINCT userId, eventType = 'view') as viewUsers,
        countIf(DISTINCT userId, eventType = 'add_to_cart') as cartUsers,
        countIf(DISTINCT userId, eventType = 'purchase') as purchaseUsers,
        cartUsers / viewUsers as viewTocCartRate,
        purchaseUsers / cartUsers as cartToPurchaseRate,
        purchaseUsers / viewUsers as overallConversionRate
      FROM currentDatabase().ProductEvent
      WHERE eventType IN ('view', 'add_to_cart', 'purchase')
    `,
    orderByFields: ["totalUsers"],
  },
});

