import { AggregateView } from "@514labs/moose-lib";

export interface HourlyActivity {
  hour: Date;
  totalEvents: number;
  views: number;
  addToCarts: number;
  purchases: number;
  uniqueUsers: number;
  revenue: number;
}

export const HourlyActivityView = new AggregateView<HourlyActivity>({
  name: "HourlyActivity",
  destination: "HourlyActivity_mv",
  materializedView: {
    query: `
      SELECT
        toStartOfHour(timestamp) as hour,
        count() as totalEvents,
        countIf(eventType = 'view') as views,
        countIf(eventType = 'add_to_cart') as addToCarts,
        countIf(eventType = 'purchase') as purchases,
        uniq(userId) as uniqueUsers,
        sumIf(JSONExtractFloat(properties, 'price'), eventType = 'purchase') as revenue
      FROM currentDatabase().ProductEvent
      GROUP BY hour
      ORDER BY hour DESC
    `,
    orderByFields: ["hour"],
  },
});

