  hours?: number; // Number of hours to look back
}

interface HourlyActivityResponse {
  hour: string;
  totalEvents: number;
  views: number;
  addToCarts: number;
  purchases: number;
  uniqueUsers: number;
  revenue: number;
}

export const hourlyActivityApi = new Api<HourlyActivityParams, HourlyActivityResponse[]>(
  "hourly",
  async ({ hours = 24 }, { client, sql }) => {
    const result = await client.query.execute(
      sql.statement`
        SELECT
          formatDateTime(hour, '%Y-%m-%d %H:%M:%S') as hour,
          totalEvents,
          views,
          addToCarts,
          purchases,
          uniqueUsers,
          revenue
        FROM currentDatabase().HourlyActivity_mv
        WHERE hour >= now() - INTERVAL ${hours} HOUR
        ORDER BY hour DESC
      `
    );
    return result;
  }
);

