### Modify Materialized View SELECT Statement (TypeScript)

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/olap/apply-migrations.mdx

Before and after TypeScript code demonstrating the modification of a materialized view's SELECT statement to include an additional aggregated column.

```typescript
import { sql } from "@514-labs/moose-lib";

interface TargetSchema {
  day: Date;
  count: number;
  sum: number;
}

const selectStatement = sql.statement`
  SELECT
    toStartOfDay(${sourceTable.columns.a_date}) as day,
    uniq(${sourceTable.columns.id}) as count,
    SUM(${sourceTable.columns.a_number}) as sum
    FROM ${sourceTable}
    GROUP BY day
`;

const mv = new MaterializedView<Target>({
  selectStatement,
  selectTables: [sourceTable],
  targetTable: {
    name: "target_table",
    engine: ClickHouseEngines.MergeTree,
    orderByFields: ["day"],
  },
  materializedViewName: "mv_table_to_target",
});
```

```typescript
