import { getMooseUtils } from "@514labs/moose-lib";

export async function insertSampleData() {
  const { client } = await getMooseUtils();

  // Sample product events data
  const sampleEvents = [
    {
      eventId: "evt_001",
      userId: "user_001",
      productId: "prod_001",
      eventType: "view",
      timestamp: new Date("2024-04-17T10:00:00Z"),
      properties: { category: "electronics" }
    },
    {
      eventId: "evt_002",
      userId: "user_001",
      productId: "prod_001",
      eventType: "add_to_cart",
      timestamp: new Date("2024-04-17T10:05:00Z"),
      properties: { category: "electronics" }
    },
    {
      eventId: "evt_003",
      userId: "user_001",
      productId: "prod_001",
      eventType: "purchase",
      timestamp: new Date("2024-04-17T10:10:00Z"),
      properties: { price: 29.99, category: "electronics" }
    },
    {
      eventId: "evt_004",
      userId: "user_002",
      productId: "prod_002",
      eventType: "view",
      timestamp: new Date("2024-04-17T11:00:00Z"),
      properties: { category: "books" }
    },
    {
      eventId: "evt_005",
      userId: "user_002",
      productId: "prod_002",
      eventType: "purchase",
      timestamp: new Date("2024-04-17T11:15:00Z"),
      properties: { price: 19.99, category: "books" }
    }
  ];

  console.log("Inserting sample data...");

  for (const event of sampleEvents) {
    try {
      const response = await fetch("http://localhost:3000/ingest/ProductEvent", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(event),
      });

      if (!response.ok) {
        console.error(`Failed to insert event ${event.eventId}:`, await response.text());
      } else {
        console.log(`✓ Inserted event ${event.eventId}`);
      }
    } catch (error) {
      console.error(`Error inserting event ${event.eventId}:`, error);
    }
  }

  console.log("Sample data insertion completed.");
}

// Run if called directly
if (require.main === module) {
  insertSampleData().catch(console.error);
}

