import { MaterializedView, sql, ClickHouseEngines } from "@514labs/moose-lib";
import { ProductEventPipeline } from "../models/ProductEvent";

export interface TopProducts {
  productId: string;
  purchaseCount: number;
  totalRevenue: number;
  lastPurchase: Date;
}

const sourceTable = ProductEventPipeline.table!;

export const TopProductsView = new MaterializedView<TopProducts>({
  tableName: "TopProducts",
  materializedViewName: "TopProducts_mv",
  orderByFields: ["purchaseCount", "totalRevenue"],
  selectTables: [sourceTable],
  selectStatement: sql`
    SELECT
      productId,
      count() as purchaseCount,
      sum(JSONExtractFloat(properties, 'price')) as totalRevenue,
      max(timestamp) as lastPurchase
    FROM ${sourceTable}
    WHERE eventType = 'purchase'
    GROUP BY productId
    ORDER BY purchaseCount DESC, totalRevenue DESC
  `,
});

import { MaterializedView, sql } from "@514labs/moose-lib";
import { ProductEventPipeline } from "../models/ProductEvent";

export interface HourlyActivity {
  hour: Date;
  totalEvents: number;
  views: number;
  addToCarts: number;
  purchases: number;
  uniqueUsers: number;
  revenue: number;
}

const sourceTable = ProductEventPipeline.table!;

export const HourlyActivityView = new MaterializedView<HourlyActivity>({
  tableName: "HourlyActivity",
  materializedViewName: "HourlyActivity_mv",
  orderByFields: ["hour"],
  selectTables: [sourceTable],
  selectStatement: sql`
    SELECT
      toStartOfHour(timestamp) as hour,
      count() as totalEvents,
      countIf(eventType = 'view') as views,
      countIf(eventType = 'add_to_cart') as addToCarts,
      countIf(eventType = 'purchase') as purchases,
      uniq(userId) as uniqueUsers,
      sumIf(JSONExtractFloat(properties, 'price'), eventType = 'purchase') as revenue
    FROM ${sourceTable}
    GROUP BY hour
    ORDER BY hour DESC
  `,
});

