const express = require('express');
const { createClient } = require('@clickhouse/client');

const app = express();
app.use(express.json());

// ClickHouse client
const clickhouse = createClient({
  url: 'http://localhost:18123',
  username: 'panda',
  password: 'pandapass',
  database: 'local',
});

// Top products endpoint
app.get('/api/top-products', async (req, res) => {
  try {
    const limit = parseInt(req.query.limit) || 10;

    const query = `
      SELECT
        productId,
        purchaseCount,
        totalRevenue,
        formatDateTime(lastPurchase, '%Y-%m-%d %H:%M:%S') as lastPurchase
      FROM TopProducts
      ORDER BY purchaseCount DESC, totalRevenue DESC
      LIMIT ${limit}
    `;

    const result = await clickhouse.query({ query });
    const data = await result.json();

    res.json(data);
  } catch (error) {
    console.error('Error in top-products:', error);
    res.status(500).json({ error: error.message });
  }
});

// Funnel endpoint
app.get('/api/funnel', async (req, res) => {
  try {
    const query = `
      SELECT
        totalUsers,
        viewUsers,
        cartUsers,
        purchaseUsers,
        viewToCartRate,
        cartToPurchaseRate,
        overallConversionRate
      FROM ConversionFunnel
      LIMIT 1
    `;

    const result = await clickhouse.query({ query });
    const data = await result.json();

    const response = data[0] || {
      totalUsers: 0,
      viewUsers: 0,
      cartUsers: 0,
      purchaseUsers: 0,
      viewToCartRate: 0,
      cartToPurchaseRate: 0,
      overallConversionRate: 0
    };

    res.json(response);
  } catch (error) {
    console.error('Error in funnel:', error);
    res.status(500).json({ error: error.message });
  }
});

// Hourly activity endpoint
app.get('/api/hourly', async (req, res) => {
  try {
    const hours = parseInt(req.query.hours) || 24;

    const query = `
      SELECT
        formatDateTime(hour, '%Y-%m-%d %H:%M:%S') as hour,
        totalEvents,
        views,
        addToCarts,
        purchases,
        uniqueUsers,
        revenue
      FROM HourlyActivity
      WHERE hour >= now() - INTERVAL ${hours} HOUR
      ORDER BY hour DESC
    `;

    const result = await clickhouse.query({ query });
    const data = await result.json();

    res.json(data);
  } catch (error) {
    console.error('Error in hourly:', error);
    res.status(500).json({ error: error.message });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', apis: ['top-products', 'funnel', 'hourly'] });
});

const PORT = 3001;
app.listen(PORT, () => {
  console.log(`API server running on port ${PORT}`);
  console.log(`Available endpoints:
  - GET /api/top-products?limit=N
  - GET /api/funnel
  - GET /api/hourly?hours=N
  - GET /health`);
});

