const express = require('express');
const { createClient } = require('@clickhouse/client');

const app = express();
app.use(express.json());

// ClickHouse client
const clickhouse = createClient({
  url: 'http://localhost:18123',
  username: 'panda',
  password: 'pandapass',
  database: 'local',
});

// Helper to extract only data from ClickHouse response
const extractData = (result) => {
  if (result.data) {
    return result.data;
  }
  return result;
};

// Top products endpoint
app.get('/api/top-products', async (req, res) => {
  try {
    const limit = parseInt(req.query.limit) || 10;

    // Query directly from ProductEvent table with aggregation
    const query = `
      SELECT
        productId,
        count() as purchaseCount,
        sum(JSONExtractFloat(properties, 'price')) as totalRevenue,
        max(timestamp) as lastPurchase
      FROM ProductEvent
      WHERE eventType = 'purchase'
      GROUP BY productId
      ORDER BY purchaseCount DESC, totalRevenue DESC
      LIMIT ${limit}
    `;

    const result = await clickhouse.query({ query });
    const data = await result.json();

    res.json(extractData(data));
  } catch (error) {
    console.error('Error in top-products:', error);
    res.status(500).json({ error: error.message });
  }
});

// Funnel endpoint
app.get('/api/funnel', async (req, res) => {
  try {
    // Calculate funnel metrics directly from ProductEvent
    const query = `
      SELECT
        count(DISTINCT userId) as totalUsers,
        countIf(DISTINCT userId, eventType = 'view') as viewUsers,
        countIf(DISTINCT userId, eventType = 'add_to_cart') as cartUsers,
        countIf(DISTINCT userId, eventType = 'purchase') as purchaseUsers
      FROM ProductEvent
    `;

    const result = await clickhouse.query({ query });
    const data = await result.json();
    const metrics = extractData(data)[0];

    // Calculate conversion rates
    const response = {
      totalUsers: metrics.totalUsers || 0,
      viewUsers: metrics.viewUsers || 0,
      cartUsers: metrics.cartUsers || 0,
      purchaseUsers: metrics.purchaseUsers || 0,
      viewToCartRate: metrics.viewUsers > 0 ? (metrics.cartUsers / metrics.viewUsers) : 0,
      cartToPurchaseRate: metrics.cartUsers > 0 ? (metrics.purchaseUsers / metrics.cartUsers) : 0,
      overallConversionRate: metrics.viewUsers > 0 ? (metrics.purchaseUsers / metrics.viewUsers) : 0
    };

    res.json(response);
  } catch (error) {
    console.error('Error in funnel:', error);
    res.status(500).json({ error: error.message });
  }
});

// Hourly activity endpoint
app.get('/api/hourly', async (req, res) => {
  try {
    const hours = parseInt(req.query.hours) || 24;

    // Query directly from ProductEvent with proper hourly aggregation
    const query = `
      SELECT
        toStartOfHour(timestamp) as hour,
        count() as totalEvents,
        countIf(eventType = 'view') as views,
        countIf(eventType = 'add_to_cart') as addToCarts,
        countIf(eventType = 'purchase') as purchases,
        uniq(userId) as uniqueUsers,
        sumIf(JSONExtractFloat(properties, 'price'), eventType = 'purchase') as revenue
      FROM ProductEvent
      WHERE timestamp >= now() - INTERVAL ${hours} HOUR
      GROUP BY hour
      ORDER BY hour DESC
    `;

    const result = await clickhouse.query({ query });
    const data = await result.json();

    res.json(extractData(data));
  } catch (error) {
    console.error('Error in hourly:', error);
    res.status(500).json({ error: error.message });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', apis: ['top-products', 'funnel', 'hourly'] });
});

const PORT = 3001;
app.listen(PORT, () => {
  console.log(`API server running on port ${PORT}`);
  console.log(`Available endpoints:
  - GET /api/top-products?limit=N
  - GET /api/funnel
  - GET /api/hourly?hours=N
  - GET /health`);
});

